private.reference_solution:
if (!long.TryParse(Console.ReadLine(), out var n) || n < 0 || n > 90) Environment.Exit(1);
Console.WriteLine(Fib(n));

static long Fib(long n)
{
    long previous = 0;
    long current = 1;
    for (long i = 0; i < n; i++)
    {
        var next = previous + current;
        previous = current;
        current = next;
    }
    return previous;
}
